import os, json, ast
from pathlib import Path

inputs = Path('/inputs')
work = Path('/work')

# Required inert read of reference text
ref_path = inputs / 'smell-catalog.md'
if ref_path.exists():
    _ = ref_path.read_text(encoding='utf-8')

# Collect top-level included Python source files
all_py = [p for p in inputs.iterdir() if p.is_file() and p.suffix == '.py']

def included(p: Path) -> bool:
    n = p.name
    if n == '__init__.py':
        return False
    if n.startswith('test_'):
        return False
    if n.endswith('_test.py'):
        return False
    return True

files = sorted([p for p in all_py if included(p)], key=lambda p: p.name)
stems = {p.stem for p in files}

# line counts with splitlines semantics
line_counts = {}
texts = {}
for p in files:
    t = p.read_text(encoding='utf-8')
    texts[p.stem] = t
    line_counts[p.stem] = len(t.splitlines())

# import graph edges: stem -> set(stem)
imports = {p.stem: set() for p in files}

for p in files:
    stem = p.stem
    t = texts[stem]
    try:
        tree = ast.parse(t, filename=str(p))
    except SyntaxError:
        # If unparsable, no reliably extractable static imports via AST
        continue

    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                name = alias.name
                # explicit absolute imports under skillc.frontend
                if name == 'skillc.frontend':
                    continue
                prefix = 'skillc.frontend.'
                if name.startswith(prefix):
                    rest = name[len(prefix):]
                    if rest:
                        comp = rest.split('.')[0]
                        if comp in stems and comp != stem:
                            imports[stem].add(comp)
        elif isinstance(node, ast.ImportFrom):
            lvl = node.level or 0
            mod = node.module

            if lvl == 0:
                # explicit absolute-package forms under skillc.frontend
                if mod == 'skillc.frontend':
                    for alias in node.names:
                        nm = alias.name
                        if nm == '*':
                            continue
                        comp = nm.split('.')[0]
                        if comp in stems and comp != stem:
                            imports[stem].add(comp)
                elif mod and mod.startswith('skillc.frontend.'):
                    rest = mod[len('skillc.frontend.'):]
                    if rest:
                        comp = rest.split('.')[0]
                        if comp in stems and comp != stem:
                            imports[stem].add(comp)
            elif lvl == 1:
                # level-one relative imports
                if mod:
                    comp = mod.split('.')[0]
                    if comp in stems and comp != stem:
                        imports[stem].add(comp)
                else:
                    # from . import module
                    for alias in node.names:
                        nm = alias.name
                        if nm == '*':
                            continue
                        comp = nm.split('.')[0]
                        if comp in stems and comp != stem:
                            imports[stem].add(comp)
            else:
                # relative imports above package ignored
                pass

# Build files list
files_rows = []
for p in files:
    st = p.stem
    files_rows.append({
        'name': p.name,
        'lines': int(line_counts[st]),
        'imports': sorted(f'{m}.py' for m in imports[st])
    })

# Prefix clusters
stems_list = sorted(stems)
prefix_to_members = {}
for st in stems_list:
    for L in range(4, len(st) + 1):
        pref = st[:L]
        if pref not in prefix_to_members:
            members = frozenset(s for s in stems_list if s.startswith(pref))
            prefix_to_members[pref] = members

eligible = {p: m for p, m in prefix_to_members.items() if len(m) >= 3}

# collapse identical member sets
set_to_prefix = {}
for pref, members in eligible.items():
    set_to_prefix.setdefault(members, []).append(pref)

def longest_common_prefix(strings):
    if not strings:
        return ''
    s1 = min(strings)
    s2 = max(strings)
    i = 0
    n = min(len(s1), len(s2))
    while i < n and s1[i] == s2[i]:
        i += 1
    return s1[:i]

prefix_rows = []
for members, prefs in set_to_prefix.items():
    mem = sorted(members)
    lcp = longest_common_prefix(mem)
    row_prefix = lcp
    files_basenames = [f'{m}.py' for m in mem]
    total_lines = int(sum(line_counts[m] for m in mem))
    prefix_rows.append({'prefix': row_prefix, 'files': files_basenames, 'lines': total_lines})

prefix_rows.sort(key=lambda r: r['prefix'])

# Import-tree clusters
# adjacency over basenames
adj = {f'{st}.py': sorted(f'{m}.py' for m in neigh) for st, neigh in imports.items()}

import_tree_rows = []
for root_st in sorted(stems_list):
    direct = imports[root_st]
    if len(direct) < 3:
        continue
    root = f'{root_st}.py'
    reachable = set([root_st])
    stack = list(direct)
    while stack:
        cur = stack.pop()
        if cur in reachable:
            continue
        reachable.add(cur)
        for nxt in imports.get(cur, set()):
            if nxt not in reachable:
                stack.append(nxt)
    if len(reachable) >= 5:
        files_sorted = sorted(f'{m}.py' for m in reachable)
        total_lines = int(sum(line_counts[m] for m in reachable))
        import_tree_rows.append({'root': root, 'files': files_sorted, 'lines': total_lines})

import_tree_rows.sort(key=lambda r: r['root'])

out = {
    'files': files_rows,
    'prefix_clusters': prefix_rows,
    'import_tree_clusters': import_tree_rows,
}

out_path = work / 'layout.json'
out_path.write_text(json.dumps(out, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')

# Validation: exact top-level keys
loaded = json.loads(out_path.read_text(encoding='utf-8'))
assert list(loaded.keys()) == ['files', 'prefix_clusters', 'import_tree_clusters']

print(str(out_path))
print(f"files={len(files_rows)} prefix_clusters={len(prefix_rows)} import_tree_clusters={len(import_tree_rows)}")

